import{_ as t,l as i,o as a,c as n,v as r,p as d,x as l,d as s,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"Huawei CloudMatrix384 超节点","description":"","frontmatter":{"title":"Huawei CloudMatrix384 超节点","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/cloudmatrix384-paper.md","filePath":"llm/cloudmatrix384-paper.md","lastUpdated":1789023840000}'),u={name:"llm/cloudmatrix384-paper.md"};function h(P,e,m,C,E,D){const o=i("Mermaid");return a(),n("div",null,[e[1]||(e[1]=r('<h1 id="huawei-cloudmatrix384-超节点" tabindex="-1">Huawei CloudMatrix384 超节点 <a class="header-anchor" href="#huawei-cloudmatrix384-超节点" aria-label="Permalink to &quot;Huawei CloudMatrix384 超节点&quot;">​</a></h1><div class="epigraph"><p>超节点论文要回答的不是「384 张卡怎么装箱」，而是：在统一总线上，如何把 prefill、decode 与缓存收成可独立伸缩的服务，并在宽专家并行下把 DeepSeek-R1 跑出可引用的吞吐。</p><footer>—— Zuo et al., Serving Large Language Models on Huawei CloudMatrix384, arXiv:2506.12708</footer></div><p><a href="/llm/cloudmatrix-384">CloudMatrix 384</a> 已经钉过生产 SKU：384 颗昇腾 910C、192 颗鲲鹏、16 柜、三平面。本篇读 <strong>arXiv:2506.12708</strong> 作为一篇<strong>服务系统论文</strong>：硬件只提供一块紧耦合的 Scale-Up 域；真正把 LLM 请求变成 tokens/s 的，是 CloudMatrix-Infer。论文把贡献收成三刀——对等的 Prefill–Decode–Caching（PDC）池、依托 UB 的大规模专家并行（文中示例 EP320）、以及面向 910C 的融合算子与 INT8。SKU 组成、柜数与单卡 TFLOPS 不在此重复；算子重叠见 <a href="/llm/cloudmatrix-infer">CloudMatrix-Infer</a>，池化编址见 <a href="/llm/cloudmatrix-resource-pool">资源池</a>，宽 EP 与 KV 见 <a href="/llm/cloudmatrix-moe-kv">MoE KV</a>。未在论文出现的光模块只数、未发布的 UB 包格式，不写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>MoE 变大、上下文变长之后，传统「一台 8 卡服务器 + 节点间 RDMA」会在两处同时破：张量并行与 token dispatch 一跨节点就掉到以太网档；KV 复用若绑在请求落点，缓存命中变成调度约束。论文把需求写成：计算强度、内存带宽、片间通信与延迟，再加上负载波动和硬 SLO。只加机器台数填不满 Scale-Up 这一档；只把超节点当更大的盒子、软件仍按 hostname 调度，UB 买了等于没买。</p><p>对照物是 KV-centric 的分离式服务：prefill 与 decode 拆开之后，KV 仍往往要考虑「缓存在哪台机器上」，调度带着局部性。CloudMatrix384 的主张是：域内 UB 提供高带宽、近均匀的访问，于是可以把缓存做成<strong>对等池</strong>，而不是每条请求先问数据住在哪。</p><h3 id="论文三刀-pdc、宽-ep、硬件相关核" tabindex="-1">论文三刀：PDC、宽 EP、硬件相关核 <a class="header-anchor" href="#论文三刀-pdc、宽-ep、硬件相关核" aria-label="Permalink to &quot;论文三刀：PDC、宽 EP、硬件相关核&quot;">​</a></h3><p>第一刀，PDC。Prefill 池建初始 KV 并出首 token；Decode 池自回归续写；Caching 池用超节点内 DRAM（论文还提到与 SSD 配合的分布式 KV）承接历史缓存与模型块。三者经显式 KV 传递接口通信，按负载独立加卡。论文对比：KV-centric 受数据局部性约束；peer-to-peer 降低「请求必须钉在缓存所在节点」的假设，调度更接近无状态。</p><p>第二刀，宽 EP。DeepSeek-R1 一类稀疏 MoE 的 decode 延迟，对「每 Die 一个专家、token 在超节点内 All-to-All」敏感。论文给出 EP320 量级：让 decode 集群里每颗 NPU Die 托管恰好一个专家，换更瘦的本地 GEMM 与更低的逐步延迟。910C 是双 Die 封装，计数时必须声明是封装还是 Die——384 是封装数，EP320 走的是 Die 账。</p><p>第三刀，硬件相关优化：融合 dispatch/combine、微批流水、INT8。没有这三刀，超节点只是密度更高的 8 卡集群。</p><p><span class="marginnote">EP320 是服务策略，不是超节点铭牌。不要把 320 写进「CloudMatrix384 = 320 卡」。论文用它说明 UB 上可以铺开到「每 Die 一专家」；换模型、换专家数，度数要重算。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把一篇超节点服务论文当成实验报告来读：模型、精度、SLO、分母。评测主模型是 DeepSeek-R1。公开结果：prefill <strong>6688 tokens/s/NPU</strong>（4K 输入一类设定）；decode <strong>1943 tokens/s/NPU</strong>，TPOT 低于 50 ms；在更严的 <strong>15 ms</strong> 延迟约束下仍维持 <strong>538 tokens/s/NPU</strong>。INT8 量化被写成在一组基准上保持精度，并把关键矩阵（FFN、稠密、注意力）收到 INT8，论文称相对全精度有数倍吞吐增益——具体倍数属于该文实验，不要抄成任意模型的 SLA。</p><p>软件栈落在 CANN / HCCL / MindIE 或 <a href="/llm/vllm-ascend">vLLM-Ascend</a> 一侧。并行组应落在 UB 域内：宽 TP、宽 EP 不要在超节点边界上再拼一台。域间 KV 与副本走 RDMA（RoCE）；管控与对象存储走 VPC。这与 <a href="/llm/scale-up-vs-scale-out">Scale-Up 对 Scale-Out</a> 对得上：集合通信属于超节点内，跨可用区属于超节点外。</p>',14)),(a(),d(c,null,{default:l(()=>[p(o,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20LR%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20P%5B%22Prefill%20%E6%B1%A0%22%5D%0A%20%20P%20--%3E%20C%5B%22Caching%20%E6%B1%A0%20%C2%B7%20UB%20%E5%AF%B9%E7%AD%89%E8%AE%BF%E9%97%AE%22%5D%0A%20%20C%20--%3E%20D%5B%22Decode%20%E6%B1%A0%20%C2%B7%20%E5%AE%BD%20EP%22%5D%0A%20%20D%20--%3E%20TOK%5B%22token%22%5D%0A%20%20P%20-.-%3E%20%7C%22%E6%98%BE%E5%BC%8F%20KV%22%7C%20C%0A%20%20C%20-.-%3E%20%7C%22%E6%98%BE%E5%BC%8F%20KV%22%7C%20D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h3 id="deepseek-r1-数字钉在哪一组条件" tabindex="-1">DeepSeek-R1 数字钉在哪一组条件 <a class="header-anchor" href="#deepseek-r1-数字钉在哪一组条件" aria-label="Permalink to &quot;DeepSeek-R1 数字钉在哪一组条件&quot;">​</a></h3><p>分母是每 NPU（封装）吞吐，不是每 Die、不是每超节点合计后再除以营销 PFLOPS。输入长度、batch、是否 INT8、TPOT 上限，四者缺一不可比。1943 与 538 是同一套系统在不同延迟约束下的两个工作点：松约束吃吞吐，紧约束吃 TPOT。把 6688 写成「任意 prefill 的保证」，等于丢掉 4K 设定。论文还给出 tokens/s/TFLOPS 一类归一化，用来和别的加速器比效率；那是作者的对照框架，不是本博客的测量。</p><p><span class="marginnote">INT8 自适应尺度搜索、per-token 激活与 per-channel 权重，是论文量化节的方法，不是「昇腾只支持 INT8」。精度表覆盖哪些基准，以原文表格为准，不要外推成所有安全关键任务都已过关。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>PDC 能对等，靠的是 UB 同时提供内存语义与消息语义，见 <a href="/llm/ub-lingqu">灵衢</a>：KV 页、专家缓冲可以按全局可寻址对象登记，而不先经过本机内核两次拷贝。论文写缓存实例相对本地复制，DRAM 开销可以从「每实例一份完整副本」降到池化后的更低倍数——那是该文缓存设计的账，用来理解「池化改的是访问语义」，不是把 384 张卡融进一个 <code>cudaMalloc</code>。</p><p>宽 EP 的机制是：decode 一步工作集小，专家若挤在少数卡上，GEMM 太肥、通信突发太尖；铺到每 Die 一专家，本地计算变瘦，dispatch 体积按 token 走 UB。FusedDispatch 在发送前量化以缩小消息，AIV-Direct 经 UB 直写对端预分配缓冲，躲开 SDMA 启动税。这与 GPU 上 DeepSeek 双微批思路同族，但是 910C 的 AIC/AIV/SDMA 异构核上的改写。</p><h3 id="对等访问如何改调度假设" tabindex="-1">对等访问如何改调度假设 <a class="header-anchor" href="#对等访问如何改调度假设" aria-label="Permalink to &quot;对等访问如何改调度假设&quot;">​</a></h3><p>KV-centric 调度必须问：这条前缀的缓存在哪，跨节点搬不划算就粘在原节点，于是出现热点与空洞。UB 域内搬 KV 的成本被论文写成可接受之后，调度可以按计算空闲度派 prefill/decode，缓存命中变成池的命中率，而不是节点的命中率。代价是故障域变成超节点：通信柜或一条 L2 子平面影响整块逻辑节点，维护窗口按 16 柜设计，集群应能把该超节点从副本集摘掉。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把 NVL72 的托盘抄成 12+4 柜。不要在没有 UB 的普通 8 卡集群上用 64 路 TP「模拟 384」。不要把 R1 的 6688 / 1943 / 538 写成任意模型、任意精度的 SLA。不要把论文里规划的更大超节点、CPU 物理分解，当成 384 这一代已经交付的形态——这一代仍是节点内 8 NPU + 4 CPU 的固定配比，逻辑上池化。</p><p>软件生态与硬件是否已经是一块逻辑节点，是两笔账。论文是华为作者在自有超节点上的系统报告，对照 GPU 数字来自作者设定的基准，读的时候分开「超节点内相对自己基线的增益」和「跨厂商屋顶线」。</p><p><span class="marginnote">出处：arXiv:2506.12708。UB-Mesh 拓扑见 arXiv:2503.20377；本篇只把 384 的 UB 当作其递归落地来引用，不把 4D-Pod 的 1024 NPU 设计与 384 SKU 画等号。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CloudMatrix384 论文的主体是服务系统 CloudMatrix-Infer，不是装箱清单。</li><li>三刀：PDC 对等池、UB 上宽 EP（示例 EP320）、910C 相关融合与 INT8。</li><li>DeepSeek-R1：prefill 6688、decode 1943（TPOT 低于 50 ms）、15 ms 约束下 538 tokens/s/NPU，均钉原文设定。</li><li>出处：Zuo et al.，arXiv:2506.12708。</li></ul>',14))])}const A=t(u,[["render",h]]);export{x as __pageData,A as default};
